 p.abilityCooldowns=p.abilityCooldowns||{};p.stamina=Math.max(0,p.stamina-a.cost);p.abilityCooldowns[id]=time+a.cooldown;
 p.abilityGlobalUntil=time+Math.max(34,Math.min(72,Math.round(a.duration*.7)));
 p.activeAbility={id,start:time,until:time+a.duration};p.activeAbilities=p.activeAbilities||{};p.activeAbilities[a.stat]={id,start:time,until:time+a.duration};
 p.abilityUses=p.abilityUses||{};p.abilityUses[id]=(p.abilityUses[id]||0)+1;p.abilityLastId=id;return a;
